// === Tab: mySketch ===


let flock;

function setup() {
  createCanvas(windowWidth, windowHeight);
	colorMode(HSB, 360);
	colors = [280, 1, 40, 140, 180, 240, 300, 340];
	startColor = random(colors);
	endColor = startColor + 40;
	if(endColor > 360) endColor = abs(360 - endColor);

  flock = new Flock();
  for (let i = 0; i < 50; i++) {
    let p = new Particle(width / 2,height / 2);
    flock.addParticle(p);
  }
}

function draw() {
  background(0);
  flock.run();
}

function mouseDragged() {
  flock.addParticle(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
}

class Flock {
	constructor() {
		this.particles = [];
	}

	run() {
		for (let i = 0; i < this.particles.length; i++) {
			this.particles[i].run(this.particles, i);
		}
	}

	addParticle(b) {
		this.particles.push(b);
	}
}

function Connection(start, end) {
    this.start = start;
    this.end = end;

    this.show = function(num) {
				max_connections = max(num, 10);
        let color = lerp(startColor, endColor, num/max_connections);
        stroke(color, 360, 360);
				strokeWeight(1);
        line(this.start.x, this.start.y, this.end.x, this.end.y);
    }
}

class Particle {
	constructor(x, y) {
		this.acceleration = createVector(0, 0);
		this.velocity = createVector(random(-1, 1), random(-1, 1));
		this.position = createVector(x, y);
		this.r = 3.0;
		this.maxspeed = 3;
		this.maxforce = 0.05;

		this.connections = []
		this.num_connections = 0
	}

	run(particles, index) {
		this.flock(particles);
		this.update();
		this.borders();
		this.connect(particles.slice(index));
		this.render();
	}

	applyForce(force) {
		this.acceleration.add(force);
	}

	flock(particles) {
		let sep = this.separate(particles);
		let ali = this.align(particles);
		let coh = this.cohesion(particles);
		sep.mult(1.5);
		ali.mult(1.0);
		coh.mult(1.0);

		this.applyForce(sep);
		this.applyForce(ali);
		this.applyForce(coh);
	}

	update() {
		this.velocity.add(this.acceleration);
		this.velocity.limit(this.maxspeed);
		this.position.add(this.velocity);
		this.acceleration.mult(0);
	}

	seek(target) {
		let desired = p5.Vector.sub(target,this.position);
		desired.normalize();
		desired.mult(this.maxspeed);
		let steer = p5.Vector.sub(desired,this.velocity);
		steer.limit(this.maxforce);
		return steer;
	}

	render() {
		for(let i = 0; i < this.connections.length; i++) {
			this.connections[i].show(this.num_connections);
		}

		this.connections = [];
    this.num_connections = 0;
	}

	borders() {
		if (this.position.x < -this.r)  this.position.x = width + this.r;
		if (this.position.y < -this.r)  this.position.y = height + this.r;
		if (this.position.x > width + this.r) this.position.x = -this.r;
		if (this.position.y > height + this.r) this.position.y = -this.r;
	}

	separate(particles) {
		let desiredseparation = 25.0;
		var steer = createVector(0, 0);
		let count = 0;

		for (let i = 0; i < particles.length; i++) {
			let d = p5.Vector.dist(this.position,particles[i].position);
			if ((d > 0) && (d < desiredseparation)) {
				let diff = p5.Vector.sub(this.position, particles[i].position);
				diff.normalize();
				diff.div(d);
				steer.add(diff);
				count++;
			}
		}

		if (count > 0) {
			steer.div(count);
		}

		if (steer.mag() > 0) {
			steer.normalize();
			steer.mult(this.maxspeed);
			steer.sub(this.velocity);
			steer.limit(this.maxforce);
		}
		return steer;
	}

	connect(particles) {
		let neighbordist = 50;
		var count = 0

		for (let i = 0; i < particles.length; i++) {
			var d = p5.Vector.dist(this.position,particles[i].position);
			if ((d > 0) && (d < neighbordist)) {
				this.connections.push(new Connection(this.position, particles[i].position));
				this.num_connections++;
			}
		}
	}

	align(particles) {
		var neighbordist = 50;
		let sum = createVector(0,0);
		var count = 0;
		for (let i = 0; i < particles.length; i++) {
			var d = p5.Vector.dist(this.position,particles[i].position);
			if ((d > 0) && (d < neighbordist)) {
				sum.add(particles[i].velocity);
				count++;
			}
		}
		if (count > 0) {
			sum.div(count);
			sum.normalize();
			sum.mult(this.maxspeed);
			var steer = p5.Vector.sub(sum, this.velocity);
			steer.limit(this.maxforce);
			return steer;
		} else {
			return createVector(0, 0);
		}
	}

	cohesion(particles) {
		var neighbordist = 50;
		var sum = createVector(0, 0);
		var count = 0;
		for (let i = 0; i < particles.length; i++) {
			var d = p5.Vector.dist(this.position,particles[i].position);
			if ((d > 0) && (d < neighbordist)) {
				sum.add(particles[i].position);
				count++;
			}
		}
		if (count > 0) {
			sum.div(count);
			return this.seek(sum);
		} else {
			return createVector(0, 0);
		}
	}
}

